import React, { useState, useEffect, useRef } from 'react';
import styled from 'styled-components';
import Logout from './Logout';
import ChatInput from './ChatInput';
import Messages from './Messages';
import axios from 'axios';
import { getAllMessageRoute, sendMessageRoute } from '../utils/APIRoutes';
import { v4 as uuidv4 } from 'uuid';

export default function ChatContainer({ currentChat, currentUser, socket }) {
  const [messages, setMessages] = useState([]);
  const [arrivalMessage, setArraivalMessage] = useState(null);
  const scrollRef = useRef();

  useEffect(() => {
    async function fetchMsg() {
      if (currentChat) {
        const response = await axios.post(getAllMessageRoute, {
          from: currentUser._id,
          to: currentChat._id,
        });
        setMessages(response.data);
      }
    }
    fetchMsg();
  }, [currentChat]);

  const handleSendMsg = async (msg) => {
    await axios.post(sendMessageRoute, {
      from: currentUser._id,
      to: currentChat._id,
      message: msg,
    });
    socket.current.emit('send-msg', {
      to: currentChat._id,
      from: currentUser._id,
      message: msg,
    });
    const msgs = [...messages];
    msgs.push({ fromSelf: true, message: msg });
    setMessages(msgs);
  };
  useEffect(() => {
    if (socket.current) {
      socket.current.on('msg-received', (msg) => {
        setArraivalMessage({ fromSelf: false, message: msg });
      });
    }
  }, []);
  useEffect(() => {
    arrivalMessage && setMessages((prev) => [...prev, arrivalMessage]);
  }, [arrivalMessage]);
  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behaviour: 'smooth' });
  }, [messages]);

  return (
    <Container>
      {/* Header */}
      <div className="chat_header">
        {/* User Info */}
        <div className="left">
          <div className="avatar">
            <img src={currentChat.profileImage} alt="" />
          </div>
          <div className="username">
            {/* <h3>{currentChat.username}</h3> */}
            <h3>
              Lorem ipsum dolor, sit amet consectetur adipisicing elit. Alias
              voluptatem illo tempore.
            </h3>
          </div>
        </div>
        {/* Menu's */}
        <div className="menu">
          <ion-icon name="ellipsis-vertical-outline"></ion-icon>
        </div>
      </div>
      <div className="chat_messages">
        {messages.map((msg) => {
          return (
            <div key={uuidv4()} ref={scrollRef}>
              <div
                className={`message ${msg.fromSelf ? 'sender' : 'receiver'}`}
              >
                <div className="content">
                  <p>{msg.message}</p>
                </div>
              </div>
            </div>
          );
        })}
      </div>
      {/* <Messages /> */}
      {/* <div className="chat_input"></div> */}
      <ChatInput handleSendMsg={handleSendMsg} />
    </Container>
  );
}

const Container = styled.div`
  flex: 0 1 65%;
  background-color: #14021d;
  display: flex;
  flex-direction: column;
  border-radius: 12px;
  min-width: 0;
  /* overflow: hidden; */
  .chat_header {
    height: 75px;
    display: flex;
    padding: 9px;
    column-gap: 10px;
    justify-content: space-between;
    align-items: center;
    background: #1b0029;
    color: #fff;
    border-radius: 12px 12px 0 0;
    /* overflow: none; */
    .left {
      display: flex;
      align-items: center;
      column-gap: 10px;
      min-width: 0;
      .avatar {
        overflow: hidden;
        height: 60px;
        min-width: 60px;
        border-radius: 100%;
        img {
          height: 100%;
          width: 100%;
          object-fit: cover;
        }
      }
      .username {
        overflow: hidden;
        h3 {
          flex: 1;
          overflow: hidden;
          white-space: nowrap;
          text-overflow: ellipsis;
          font: 400 1.4rem var(--ralewayFont);
        }
      }
    }
    .menu {
      width: 25px;
      height: 100%;
      background-color: limegreen;
    }
  }
`;

